def solve(inputs: dict) -> float:
    terms = inputs['terms']

    # Compute convergents using the standard recurrence
    # p_{-1} = 1, p_0 = a_0
    # p_n = a_n * p_{n-1} + p_{n-2}

    if len(terms) == 0:
        return 0.0

    p_prev2 = 1  # p_{-1}
    p_prev1 = terms[0]  # p_0

    if len(terms) == 1:
        return float(p_prev1)

    for i in range(1, len(terms)):
        p_curr = terms[i] * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p_curr

    return float(p_prev1)

